"use strict";

class CircularBuffer {
  #buf;
  #capacity;
  #head = 0;
  #size = 0;

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1)
      throw new RangeError("capacity must be a positive integer");
    this.#capacity = capacity;
    this.#buf = new Array(capacity).fill(null);
  }

  enqueue(item) {
    const tail = (this.#head + this.#size) % this.#capacity;
    this.#buf[tail] = item;
    if (this.#size === this.#capacity) {
      this.#head = (this.#head + 1) % this.#capacity;
    } else {
      this.#size++;
    }
  }

  dequeue() {
    if (this.#size === 0) throw new RangeError("dequeue from empty buffer");
    const item = this.#buf[this.#head];
    this.#buf[this.#head] = null;
    this.#head = (this.#head + 1) % this.#capacity;
    this.#size--;
    return item;
  }

  peek() {
    if (this.#size === 0) throw new RangeError("peek on empty buffer");
    return this.#buf[this.#head];
  }

  peekRight() {
    if (this.#size === 0) throw new RangeError("peekRight on empty buffer");
    return this.#buf[(this.#head + this.#size - 1) % this.#capacity];
  }

  clear() {
    this.#buf.fill(null);
    this.#head = 0;
    this.#size = 0;
  }

  get capacity() {
    return this.#capacity;
  }

  get size() {
    return this.#size;
  }

  get isEmpty() {
    return this.#size === 0;
  }

  get isFull() {
    return this.#size === this.#capacity;
  }

  *[Symbol.iterator]() {
    for (let i = 0; i < this.#size; i++) {
      yield this.#buf[(this.#head + i) % this.#capacity];
    }
  }

  toArray() {
    return [...this];
  }

  toString() {
    return `CircularBuffer([${this.toArray().map((v) => JSON.stringify(v)).join(", ")}], capacity=${this.#capacity})`;
  }
}

module.exports = { CircularBuffer };

const { CircularBuffer } = require("./circular_buffer");

let passed = 0;
let failed = 0;
const failures = [];

function assert(cond, msg) {
  if (!cond) {
    failed++;
    failures.push(msg);
  } else {
    passed++;
  }
}

function assertEq(actual, expected, msg) {
  if (actual !== expected) {
    failed++;
    failures.push(`${msg}: got ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`);
  } else {
    passed++;
  }
}

function assertThrows(fn, errType, msg) {
  try {
    fn();
    failed++;
    failures.push(`${msg} — expected error, none thrown`);
  } catch (e) {
    if (!(e instanceof errType)) {
      failed++;
      failures.push(`${msg} — expected ${errType.name}, got ${e.constructor.name}`);
    } else {
      passed++;
    }
  }
}

function run() {
  // ── Constructor validation ────────────────────────────────────────
  console.log("constructor validation");
  assertThrows(() => new CircularBuffer(0), RangeError, "capacity 0");
  assertThrows(() => new CircularBuffer(-1), RangeError, "negative capacity");
  assertThrows(() => new CircularBuffer(1.5), RangeError, "float capacity");

  // ── Enqueue and iteration ─────────────────────────────────────────
  console.log("enqueue and iteration");
  const cb = new CircularBuffer(3);
  cb.enqueue(1);
  cb.enqueue(2);
  cb.enqueue(3);
  assertEq(cb.size, 3, "size after 3 enqueues");
  assertEq(cb.isFull, true, "full after 3 enqueues");
  assertEq(cb.isEmpty, false, "not empty");
  assert(cb.toArray().join(",") === "1,2,3", "iteration order");

  // ── Overwrite when full ───────────────────────────────────────────
  console.log("overwrite when full");
  cb.enqueue(4);
  assertEq(cb.size, 3, "size stays at capacity");
  assert(cb.toArray().join(",") === "2,3,4", "oldest overwritten");

  // ── Dequeue ───────────────────────────────────────────────────────
  console.log("dequeue");
  const d = new CircularBuffer(3);
  d.enqueue(10);
  d.enqueue(20);
  assertEq(d.dequeue(), 10, "dequeue first");
  assertEq(d.dequeue(), 20, "dequeue second");
  assertEq(d.size, 0, "empty after dequeue all");
  assertEq(d.isEmpty, true, "isEmpty after dequeue all");

  // ── Dequeue from empty throws ─────────────────────────────────────
  console.log("dequeue from empty");
  assertThrows(() => d.dequeue(), RangeError, "dequeue empty");

  // ── Peek ──────────────────────────────────────────────────────────
  console.log("peek");
  const p = new CircularBuffer(2);
  p.enqueue("a");
  assertEq(p.peek(), "a", "peek returns oldest");
  p.enqueue("b");
  assertEq(p.peek(), "a", "peek still oldest");
  assertEq(p.peekRight(), "b", "peekRight returns newest");
  assertEq(p.size, 2, "peek doesn't change size");

  // ── Peek on empty throws ──────────────────────────────────────────
  console.log("peek on empty");
  const empty = new CircularBuffer(1);
  assertThrows(() => empty.peek(), RangeError, "peek empty");
  assertThrows(() => empty.peekRight(), RangeError, "peekRight empty");

  // ── Clear ─────────────────────────────────────────────────────────
  console.log("clear");
  const cl = new CircularBuffer(3);
  cl.enqueue(1);
  cl.enqueue(2);
  cl.clear();
  assertEq(cl.size, 0, "size after clear");
  assertEq(cl.isEmpty, true, "empty after clear");

  // ── Wrap-around stress ────────────────────────────────────────────
  console.log("wrap-around stress");
  const w = new CircularBuffer(4);
  for (let i = 0; i < 100; i++) {
    w.enqueue(i);
  }
  assertEq(w.size, 4, "size at capacity after stress");
  assert(w.toArray().join(",") === "96,97,98,99", "correct items after wrap");
  assertEq(w.peekRight(), 99, "newest after stress");

  // ── Capacity 1 ────────────────────────────────────────────────────
  console.log("capacity 1");
  const c1 = new CircularBuffer(1);
  c1.enqueue("only");
  assertEq(c1.peek(), "only", "single entry");
  c1.enqueue("new");
  assertEq(c1.peek(), "new", "overwritten");
  assertEq(c1.size, 1, "size still 1");

  // ── Iterator protocol ─────────────────────────────────────────────
  console.log("iterator protocol");
  const iter = new CircularBuffer(3);
  iter.enqueue("x");
  iter.enqueue("y");
  const arr = [];
  for (const v of iter) arr.push(v);
  assert(arr.join(",") === "x,y", "for-of works");

  // ── String representation ─────────────────────────────────────────
  console.log("toString");
  const s = new CircularBuffer(2);
  s.enqueue(42);
  const str = s.toString();
  assert(str.includes("42"), "toString includes value");
  assert(str.includes("capacity=2"), "toString includes capacity");

  // ── Summary ───────────────────────────────────────────────────────
  console.log(`\n${passed} passed, ${failed} failed`);
  if (failures.length) {
    console.error("\nFailures:");
    failures.forEach((f) => console.error(`  - ${f}`));
  }
  if (failed > 0) process.exit(1);
}

run();

package main

import "fmt"

// CircularBuffer is a fixed-size ring buffer with enqueue/dequeue semantics.
// When full, enqueue overwrites the oldest element.
type CircularBuffer struct {
	buf  []interface{}
	cap  int
	head int
	size int
}

// NewCircularBuffer creates a buffer with the given capacity (>= 1).
func NewCircularBuffer(capacity int) (*CircularBuffer, error) {
	if capacity < 1 {
		return nil, fmt.Errorf("capacity must be >= 1, got %d", capacity)
	}
	return &CircularBuffer{
		buf: make([]interface{}, capacity),
		cap: capacity,
	}, nil
}

// Enqueue appends an item. Overwrites the oldest element when full.
func (cb *CircularBuffer) Enqueue(item interface{}) {
	tail := (cb.head + cb.size) % cb.cap
	cb.buf[tail] = item
	if cb.size == cb.cap {
		cb.head = (cb.head + 1) % cb.cap
	} else {
		cb.size++
	}
}

// Dequeue removes and returns the oldest item. Returns an error when empty.
func (cb *CircularBuffer) Dequeue() (interface{}, error) {
	if cb.size == 0 {
		return nil, fmt.Errorf("dequeue from empty buffer")
	}
	item := cb.buf[cb.head]
	cb.buf[cb.head] = nil
	cb.head = (cb.head + 1) % cb.cap
	cb.size--
	return item, nil
}

// Peek returns the oldest item without removing it.
func (cb *CircularBuffer) Peek() (interface{}, error) {
	if cb.size == 0 {
		return nil, fmt.Errorf("peek on empty buffer")
	}
	return cb.buf[cb.head], nil
}

// PeekRight returns the newest item without removing it.
func (cb *CircularBuffer) PeekRight() (interface{}, error) {
	if cb.size == 0 {
		return nil, fmt.Errorf("peekRight on empty buffer")
	}
	return cb.buf[(cb.head+cb.size-1)%cb.cap], nil
}

// Clear removes all items and resets the buffer.
func (cb *CircularBuffer) Clear() {
	cb.buf = make([]interface{}, cb.cap)
	cb.head = 0
	cb.size = 0
}

// Len returns the number of items in the buffer.
func (cb *CircularBuffer) Len() int {
	return cb.size
}

// Cap returns the buffer capacity.
func (cb *CircularBuffer) Cap() int {
	return cb.cap
}

// IsEmpty reports whether the buffer has no items.
func (cb *CircularBuffer) IsEmpty() bool {
	return cb.size == 0
}

// IsFull reports whether the buffer is at capacity.
func (cb *CircularBuffer) IsFull() bool {
	return cb.size == cb.cap
}

// Items returns a snapshot of the buffer contents from oldest to newest.
func (cb *CircularBuffer) Items() []interface{} {
	result := make([]interface{}, cb.size)
	for i := 0; i < cb.size; i++ {
		result[i] = cb.buf[(cb.head+i)%cb.cap]
	}
	return result
}

