func TestNewCircularBuffer(t *testing.T) {
	t.Run("valid capacity", func(t *testing.T) {
		cb, err := NewCircularBuffer(3)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if cb.Cap() != 3 {
			t.Fatalf("expected cap 3, got %d", cb.Cap())
		}
	})

	t.Run("zero capacity", func(t *testing.T) {
		_, err := NewCircularBuffer(0)
		if err == nil {
			t.Fatal("expected error for capacity 0")
		}
	})

	t.Run("negative capacity", func(t *testing.T) {
		_, err := NewCircularBuffer(-1)
		if err == nil {
			t.Fatal("expected error for negative capacity")
		}
	})
}

func TestEnqueueDequeue(t *testing.T) {
	cb, _ := NewCircularBuffer(3)
	cb.Enqueue(1)
	cb.Enqueue(2)
	cb.Enqueue(3)

	if cb.Len() != 3 {
		t.Fatalf("expected len 3, got %d", cb.Len())
	}

	for i := 1; i <= 3; i++ {
		v, err := cb.Dequeue()
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if v != i {
			t.Fatalf("expected %d, got %v", i, v)
		}
	}

	if cb.Len() != 0 {
		t.Fatalf("expected len 0, got %d", cb.Len())
	}
	if !cb.IsEmpty() {
		t.Fatal("expected empty")
	}
}

func TestOverwriteWhenFull(t *testing.T) {
	cb, _ := NewCircularBuffer(2)
	cb.Enqueue("a")
	cb.Enqueue("b")
	cb.Enqueue("c") // overwrites "a"

	if cb.Len() != 2 {
		t.Fatalf("expected len 2, got %d", cb.Len())
	}
	if !cb.IsFull() {
		t.Fatal("expected full")
	}

	items := cb.Items()
	if items[0] != "b" || items[1] != "c" {
		t.Fatalf("expected [b, c], got %v", items)
	}
}

func TestDequeueEmpty(t *testing.T) {
	cb, _ := NewCircularBuffer(1)
	_, err := cb.Dequeue()
	if err == nil {
		t.Fatal("expected error dequeueing from empty buffer")
	}
}

func TestPeek(t *testing.T) {
	cb, _ := NewCircularBuffer(3)
	cb.Enqueue(10)
	cb.Enqueue(20)

	oldest, _ := cb.Peek()
	if oldest != 10 {
		t.Fatalf("expected 10, got %v", oldest)
	}

	newest, _ := cb.PeekRight()
	if newest != 20 {
		t.Fatalf("expected 20, got %v", newest)
	}

	if cb.Len() != 2 {
		t.Fatal("peek should not change size")
	}
}

func TestPeekEmpty(t *testing.T) {
	cb, _ := NewCircularBuffer(1)
	_, err := cb.Peek()
	if err == nil {
		t.Fatal("expected error peeking empty buffer")
	}
	_, err = cb.PeekRight()
	if err == nil {
		t.Fatal("expected error peekRight on empty buffer")
	}
}

func TestClear(t *testing.T) {
	cb, _ := NewCircularBuffer(3)
	cb.Enqueue(1)
	cb.Enqueue(2)
	cb.Clear()

	if cb.Len() != 0 {
		t.Fatalf("expected len 0, got %d", cb.Len())
	}
	if !cb.IsEmpty() {
		t.Fatal("expected empty after clear")
	}
}

func TestWrapAround(t *testing.T) {
	cb, _ := NewCircularBuffer(4)
	for i := 0; i < 100; i++ {
		cb.Enqueue(i)
	}

	if cb.Len() != 4 {
		t.Fatalf("expected len 4, got %d", cb.Len())
