	items := cb.Items()
	expected := []int{96, 97, 98, 99}
	for i, v := range items {
		if v != expected[i] {
			t.Fatalf("items[%d]: expected %d, got %v", i, expected[i], v)
		}
	}
}

func TestCapacityOne(t *testing.T) {
	cb, _ := NewCircularBuffer(1)
	cb.Enqueue("only")
	v, _ := cb.Peek()
	if v != "only" {
		t.Fatalf("expected 'only', got %v", v)
	}

	cb.Enqueue("new")
	v, _ = cb.Peek()
	if v != "new" {
		t.Fatalf("expected 'new', got %v", v)
	}
	if cb.Len() != 1 {
		t.Fatalf("expected len 1, got %d", cb.Len())
	}
}

func TestItems(t *testing.T) {
	cb, _ := NewCircularBuffer(3)
	cb.Enqueue("x")
	cb.Enqueue("y")

	items := cb.Items()
	if len(items) != 2 {
		t.Fatalf("expected 2 items, got %d", len(items))
	}
	if items[0] != "x" || items[1] != "y" {
		t.Fatalf("expected [x, y], got %v", items)
